import java.util.*;
class Exercise {
    static List<String> unique(List<String> names) {
        // 새 목록을 만들어 원본을 보호해요.
        var result = new ArrayList<String>();
        for (String name : names) {
            // 처음 만난 이름만 추가해요.
            if (!result.contains(name)) result.add(name);
        }
        return result;
    }
}

