class Exercise {
    static int count(String text) {
        // null은 문자열 메서드를 호출하기 전에 확인해요.
        if (text == null) return -1;
        try {
            int value = Integer.parseInt(text.trim());
            // 범위를 벗어난 입력도 실패로 구분해요.
            return value >= 0 ? value : -1;
        } catch (NumberFormatException e) {
            // 숫자 변환 실패만 여기에서 처리해요.
            return -1;
        }
    }
}

